    instAFoot: { en: 'This installs the <code>parallel</code> binary to <code>~/.local/bin</code>. Make sure it\'s in your <code>PATH</code>.', ru: 'Это устанавливает бинарь <code>parallel</code> в <code>~/.local/bin</code>. Убедитесь, что он в вашем <code>PATH</code>.' },
    instOptionB: { en: 'Option B: Cargo Install', ru: 'Вариант B: Cargo Install' },
