    instOptionC: { en: 'Option C: Build from Source', ru: 'Вариант C: Сборка из исходников' },
    instCDesc: { en: 'Clone the repository and build locally for development.', ru: 'Клонируйте репозиторий и соберите локально для разработки.' },
    instCFoot: { en: 'The binary will be at <code>./target/release/fathom-research</code>.', ru: 'Бинарь будет в <code>./target/release/fathom-research</code>.' },
    firstRunTitle: { en: 'First Run', ru: 'Первый запуск' },
    firstRunSub: { en: 'Run your first research session with a single command:', ru: 'Запустите первую сессию исследования одной командой:' },
    firstRunFoot: { en: 'On first run, Fathom Research will prompt you for your API key if one isn\'t configured. Results are saved to <code>./research-output/</code> by default.', ru: 'При первом запуске Fathom Research спросит ваш API-ключ, если он не настроен. Результаты по умолчанию сохраняются в <code>./research-output/</code>.' },
    configTitle: { en: 'Configuration Basics', ru: 'Основы конфигурации' },
    configSub: { en: 'Configuration is stored in <code>~/.fathom-research/config.toml</code>. All sections are optional — missing fields use defaults.', ru: 'Конфигурация хранится в <code>~/.fathom-research/config.toml</code>. Все секции опциональны — отсутствующие поля используют значения по умолчанию.' },
    cfgLocTitle: { en: 'Config Location', ru: 'Расположение конфига' },
    cfgLlmTitle: { en: 'LLM Section', ru: 'Секция LLM' },
    cfgLlmSub: { en: 'The only required configuration is your LLM provider settings:', ru: 'Единственная обязательная настройка — параметры вашего LLM-провайдера:' },
    cfgSearchTitle: { en: 'Search Backend', ru: 'Поисковый бэкенд' },
    cfgSearchSub: { en: 'Choose a search engine for web queries. <code>hybrid</code> uses the first configured backend with results:', ru: 'Выберите поисковую систему для веб-запросов. <code>hybrid</code> использует первый настроенный бэкенд с результатами:' },
    callout2: { en: 'See the full <a href="/docs/configuration">Configuration Reference</a> for all available options.', ru: 'Все доступные опции смотрите в <a href="/docs/configuration">Справочнике конфигурации</a>.' },
    tuiTitle: { en: 'TUI Mode', ru: 'Режим TUI' },
    tuiSub: { en: 'Launch the interactive terminal UI for a real-time research experience with progress tracking, tool call visualization, and conversation history.', ru: 'Запустите интерактивный терминальный интерфейс для исследования в реальном времени с отслеживанием прогресса, визуализацией вызовов инструментов и историей переписки.' },
    tuiFoot: { en: 'The TUI provides an interactive chat interface where you can type queries, watch agent progress in real time, and browse results.', ru: 'TUI предоставляет интерактивный чат-интерфейс, где вы можете вводить запросы, наблюдать за прогрессом агентов в реальном времени и просматривать результаты.' },
    httpTitle: { en: 'HTTP Server Mode', ru: 'Режим HTTP-сервера' },
    httpSub: { en: 'Start an HTTP API server for programmatic access. Supports REST endpoints and SSE streaming for real-time event delivery.', ru: 'Запустите HTTP API-сервер для программного доступа. Поддерживает REST-эндпоинты и SSE-стриминг для доставки событий в реальном времени.' },
    httpFoot: { en: 'The server starts on <code>http://localhost:8080</code> by default. Send research requests via POST:', ru: 'Сервер по умолчанию запускается на <code>http://localhost:8080</code>. Отправляйте запросы исследования через POST:' },
    nextTitle: { en: 'Next Steps', ru: 'Следующие шаги' },
