    next1Desc: { en: 'Full config.toml reference with all sections, fields, and defaults.', ru: 'Полный справочник config.toml со всеми секциями, полями и значениями по умолчанию.' },
    next2Title: { en: 'Tools Reference', ru: 'Справочник инструментов' },
    next2Desc: { en: 'Explore 50+ built-in tools for web search, OSINT, browser automation, and more.', ru: 'Изучите 50+ встроенных инструментов для веб-поиска, OSINT, автоматизации браузера и не только.' },
    next3Title: { en: 'API Reference', ru: 'API-справка' },
