    sectionLabel: { en: 'Developer API', ru: 'Developer API' },
    title: { en: 'HTTP API Reference', ru: 'HTTP API-справка' },
    desc: { en: 'Full reference for the Fathom Research REST API. Manage sessions, stream events, and control AI research agents programmatically.', ru: 'Полный справочник по REST API Fathom Research. Управляйте сессиями, стримьте события и программно управляйте ИИ-агентами.' },
    overviewTitle: { en: 'Overview', ru: 'Обзор' },
    overviewText: { en: 'The Fathom Research API is a RESTful interface for managing AI research sessions. All responses are JSON-encoded. Streaming endpoints use Server-Sent Events (SSE).', ru: 'Fathom Research API — это REST-интерфейс для управления ИИ-сессиями исследования. Все ответы закодированы в JSON. Стриминговые эндпоинты используют Server-Sent Events (SSE).' },
    baseUrlLabel: { en: 'Base URL', ru: 'Базовый URL' },
    overviewAuthText: { en: 'The API supports two authentication methods via HTTP headers:', ru: 'API поддерживает два метода аутентификации через HTTP-заголовки:' },
    authTitle: { en: 'Authentication', ru: 'Аутентификация' },
    authText: { en: 'All API requests (except <code>/health</code> and <code>/metrics</code>) require a valid API key. Keys are configured via the <code>PARALLEL_RESEARCH_API_KEYS</code> environment variable as a comma-separated list.', ru: 'Все API-запросы (кроме <code>/health</code> и <code>/metrics</code>) требуют действительный API-ключ. Ключи настраиваются через переменную окружения <code>PARALLEL_RESEARCH_API_KEYS</code> списком через запятую.' },
    authRateLimit: { en: 'Each key maps to an independent identity. Rate limiting is applied per-key: <strong>100 requests/minute</strong> for standard endpoints and <strong>10 concurrent SSE connections</strong>. Exceeding limits returns <code>429 Too Many Requests</code>.', ru: 'Каждый ключ соответствует независимой идентичности. Rate limiting применяется по ключу: <strong>100 запросов/минуту</strong> для стандартных эндпоинтов и <strong>10 одновременных SSE-соединений</strong>. Превышение лимитов возвращает <code>429 Too Many Requests</code>.' },
    authWarn: { en: '<strong>Security note:</strong> Never expose API keys in client-side code or public repositories. Use environment variables or a secrets manager.', ru: '<strong>Примечание по безопасности:</strong> никогда не раскрывайте API-ключи в клиентском коде или публичных репозиториях. Используйте переменные окружения или секретохранилище.' },
