    panelOutput: { en: 'The final assembled output, streamed token-by-token as the writer produces it.', ru: 'Финальный собранный вывод, стримится токен за токеном по мере генерации автором.' },
    panelLog: { en: 'Event log: agent spawns, tool calls with timings, warnings and findings.', ru: 'Журнал событий: запуски агентов, вызовы инструментов с таймингами, предупреждения и находки.' },
